node <<'NODE'
const fs=require('fs'), cp=require('child_process'), path=require('path'), crypto=require('crypto'), assert=require('assert/strict');
const base='docs/migration/audit-closure/e3-bridge/result-platform/';
const j=JSON.parse(fs.readFileSync(base+'provider-inputs-final.json'));
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
let ranges=0; const failures=[];
for (const e of j.sourceEvidence) {
 const b=fs.readFileSync(path.join(j.sourceRoot,e.path));
 const pin=cp.execFileSync('git',['show',j.sourceRevision+':'+e.path],{cwd:j.sourceRoot,maxBuffer:10*1024*1024});
 assert.deepEqual(b,pin,e.path+' pin'); assert.equal(hash(b),e.sha256,e.path+' hash'); assert.equal(b.length,e.bytes);
 const lines=b.toString('utf8').match(/[^\n]*\n|[^\n]+$/g)||[];
 assert.equal(lines.length,e.lines,e.path+' lines');
 for(const r of e.ranges){assert.equal(hash(Buffer.from(lines.slice(r.first-1,r.last).join(''))),r.sha256,e.path+' range');ranges++;}
}
for(const i of j.inputs) assert.equal(hash(fs.readFileSync(i.path)),i.sha256,i.path);
const docs=new Map();
function pointer(ref){const [p,s]=ref.split('#');const d=p?(docs.has(p)?docs.get(p):(docs.set(p,JSON.parse(fs.readFileSync(p))),docs.get(p))):j;return (s||'').split('/').slice(1).reduce((a,k)=>a?.[k.replace(/~1/g,'/').replace(/~0/g,'~')],d);}
for(const c of j.contracts){assert.equal(c.sourcePaths.length,c.sourceEvidenceRefs.length,c.id);c.sourcePaths.forEach((p,i)=>assert.equal(pointer(c.sourceEvidenceRefs[i]).path,p));}
for(const t of j.originalAssertionBodiesRead){assert.equal(pointer(t.evidenceRef).path,t.path);for(const a of t.originalAllocations){assert(pointer(a.filesRef).some(f=>f.path===t.path && f.sha256===pointer(t.evidenceRef).sha256),t.path);}}
const old=JSON.parse(fs.readFileSync(base+'final-local.json'));
assert.deepEqual(j.originalTestAllocation,old.originalTestAllocation); assert.deepEqual(j.inheritedGates,old.inheritedGates); assert.deepEqual(j.inheritedExecutionObligations,old.inheritedExecutionObligations);
const pkg=JSON.parse(fs.readFileSync('docs/migration/parity-test-work-packages.json'));
for(const p of j.originalTestAllocation.packages){assert.equal(pointer(p.filesRef).length,p.fileCount);assert.equal(pkg.packages[p.i].id,p.id);}
for(const gate of j.inheritedGates) assert(pointer(gate.ref),gate.id);
console.log(JSON.stringify({sourcePin:j.sourceRevision,sourceFiles:j.sourceEvidence.length,ranges,inputHashes:j.inputs.length,contracts:j.contracts.length,testBodyAssociations:j.originalAssertionBodiesRead.length,retainedAllocations:j.originalTestAllocation.packages.length,inheritedGates:j.inheritedGates.length,wholeTestFiles:pkg.packages.reduce((n,p)=>n+p.files.length,0),wholePackages:pkg.packages.length,artifacts:[base+'provider-inputs-final.md',base+'provider-inputs-final.json'].map(p=>({path:p,sha256:hash(fs.readFileSync(p))}))},null,2));
